import {it} from 'vitest';
import assert from 'node:assert/strict';
import {observeStrikes,observeMotion,observeMotionWindow,STRIKE_CONTRACT,STRIKE_V2_CONTRACT,STRIKE_V3_CONTRACT} from '../scripts/lib/strike_impact.ts';
import {impactAccount} from '../scripts/v0/optimizer/impact_accounts.ts';

it('constructs exactly the scalar records, including optional-property presence and ownership',()=>{
  let seed=0x72914afe;
  const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/2**32);
  for(const scale of [0,1e-150,1,1e150])for(let trial=0;trial<100;trial++){
    const first=3,length=2+Math.floor(random()*60);
    const motions=Array.from({length},()=>({v:{x:(random()-.5)*scale,y:(random()-.5)*scale},L:(random()-.5)*scale,R:random()*scale}));
    const contacts=motions.map(()=>random()>.5);
    const data=new Float64Array(motions.flatMap((m,i)=>[m.v.x,m.v.y,m.L,m.R,+contacts[i]]));
    for(const c of [STRIKE_CONTRACT,STRIKE_V2_CONTRACT,STRIKE_V3_CONTRACT]){
      const contact=(frame:number)=>contacts[frame-first+1];
      const scalar=c.strength==='motion'?observeMotion(first,motions,contact,c):observeStrikes(first,motions.map(m=>m.v),contact,c);
      const packed=observeMotionWindow(first,data,c);
      assert.deepStrictEqual(packed,scalar);
      for(const frame of packed){
        assert.equal(Object.hasOwn(frame,'impulse'),c.strength==='motion');
        assert.deepStrictEqual(Object.keys(frame),Object.keys(scalar[0]));
      }
      const saved=packed.map(frame=>({...frame,...(frame.impulse?{impulse:[...frame.impulse]}:{})}));
      const copy=data.slice();data.fill(999);assert.deepStrictEqual(packed,saved);data.set(copy);
    }
  }
});

it('keeps frame-zero reads first and avoids observing empty or incomplete windows',()=>{
  for(const c of [STRIKE_CONTRACT,STRIKE_V2_CONTRACT,STRIKE_V3_CONTRACT]){
    const calls:string[]=[],data=new Float64Array([1,2,3,4,0,2,3,4,5,1]);
    const engine={getLastFrameIndex:()=>1,hasContactAtFrame:(frame:number)=>{calls.push('contact'+frame);return false;},
      getCachedMotionWindow:(from:number,to:number)=>{calls.push(`window${from}:${to}`);return data;}};
    const raw=[{frame:0},{frame:1}] as any;
    const account=impactAccount(c.id),observed=account.observe(engine,raw);
    assert.deepStrictEqual(calls,['contact0','window0:1']);
    assert.deepStrictEqual(observed.slice(1),observeMotionWindow(1,data,c));
    assert.equal(observed[0].frame,0);assert.equal(Object.hasOwn(observed[0],'impulse'),c.strength==='motion');
    calls.length=0;assert.equal(account.observe(engine,raw.slice(0,1)).length,1);assert.deepStrictEqual(calls,['contact0']);
    calls.length=0;assert.deepStrictEqual(account.observe(engine,[]),[]);assert.deepStrictEqual(calls,[]);
    assert.throws(()=>account.observe(engine,[{frame:2}] as any),/metered complete window/);
  }
});

it('continues to reject nonfinite velocities under every contract',()=>{
  for(const c of [STRIKE_CONTRACT,STRIKE_V2_CONTRACT,STRIKE_V3_CONTRACT]){
    for(const value of [NaN,Infinity,-Infinity])assert.throws(()=>observeMotionWindow(1,new Float64Array([1,2,3,4,0,value,3,4,5,1]),c),/nonfinite strike observation/);
  }
});
